As the connection to intuitionistic logic alluded to above suggests,
$\LogGod[3]$ is close to intuitionistic logic. All intuitionistic
truths are tautologies in~$\LogGod[3]$, and many classical tautologies
that are not valid intuitionistically also fail to be tautologies
in~$\LogGod[3]$. For instance, the following are not tautologies:
\begin{align*}
  & p \lor \lnot p && (p \lif q) \lif (\lnot p \lor q) \\
  & \lnot\lnot p \lif p && \lnot(\lnot p \land \lnot q) \lif (p \lor q) \\
  & ((p \lif q) \lif p) \lif p && \lnot(p \lif q) \lif (p \land \lnot q)
\end{align*}
However, not every tautology of $\LogGod[3]$ is also
intuitionistically valid, e.g., $\lnot\lnot p \lor \lnot p$ or $(p
\lif q) \lor (q \lif p)$.

\begin{prob}
  Give truth tables to show that the following are tautologies
  of~$\LogGod[3]$:
  \begin{align*}
    & \lnot\lnot p \lor \lnot p\\
    & (p \lif q) \lor (q \lif p) \\
    & \lnot(p \land q) \lif (\lnot p \lor \lnot q) \\
    & (p \lif q) \lor (q \lif r) \lor (r \lif s)
  \end{align*}
\end{prob}

\begin{prob}
  Give truth tables that show that the following are not tautologies
  of~$\LogGod[3]$
  \begin{align*}
    & (p \lif q) \lif (\lnot p \lor q) \\
    & \lnot(\lnot p \land \lnot q) \lif (p \lor q) \\
    & ((p \lif q) \lif p) \lif p \\
    & \lnot(p \lif q) \lif (p \land \lnot q)
  \end{align*}
\end{prob}

\begin{prob}
  Which of the following relations hold in G\"odel logic? Give a truth table for each.
  \begin{enumerate}
    \item $p, p \lif q \Entails q$
    \item $p \lor q, \lnot p \Entails q$
    \item $p \land q \Entails p$
    \item $p \Entails p \land p$
    \item $p \Entails p \lor q$
  \end{enumerate}
\end{prob}

\end{document}

وكما يوحي الارتباط بالمنطق الحدسي المشار إليه أعلاه، فإن~$\LogGod[3]$
قريب من المنطق الحدسي. فجميع الحقائق الحدسية تحصيلات منطقية في
$\LogGod[3]$، وكثير من التحصيلات المنطقية الكلاسيكية غير الصحيحة
حدسيًا لا تكون تحصيلات في~$\LogGod[3]$ أيضًا. فمثلًا، ليست الصيغ الآتية
تحصيلات منطقية:
\begin{align*}
  & p \lor \lnot p && (p \lif q) \lif (\lnot p \lor q) \\
  & \lnot\lnot p \lif p && \lnot(\lnot p \land \lnot q) \lif (p \lor q) \\
  & ((p \lif q) \lif p) \lif p && \lnot(p \lif q) \lif (p \land \lnot q)
\end{align*}
غير أن بعض تحصيلات~$\LogGod[3]$ ليست صحيحة حدسيًا، مثل
$\lnot\lnot p \lor \lnot p$ أو~$(p \lif q) \lor (q \lif p)$.

\begin{prob}
  أعط جداول صدق تبين أن الصيغ الآتية تحصيلات منطقية في~$\LogGod[3]$:
  \begin{align*}
    & \lnot\lnot p \lor \lnot p\\
    & (p \lif q) \lor (q \lif p) \\
    & \lnot(p \land q) \lif (\lnot p \lor \lnot q) \\
    & (p \lif q) \lor (q \lif r) \lor (r \lif s)
  \end{align*}
\end{prob}

\begin{prob}
  أعط جداول صدق تبين أن الصيغ الآتية ليست تحصيلات منطقية في
  $\LogGod[3]$:
  \begin{align*}
    & (p \lif q) \lif (\lnot p \lor q) \\
    & \lnot(\lnot p \land \lnot q) \lif (p \lor q) \\
    & ((p \lif q) \lif p) \lif p \\
    & \lnot(p \lif q) \lif (p \land \lnot q)
  \end{align*}
\end{prob}

\begin{prob}
  أي العلاقات الآتية تصح في منطق غودل؟ أعط جدول صدق لكل منها.
  \begin{enumerate}
    \item $p, p \lif q \Entails q$
    \item $p \lor q, \lnot p \Entails q$
    \item $p \land q \Entails p$
    \item $p \Entails p \land p$
    \item $p \Entails p \lor q$
  \end{enumerate}
\end{prob}

\end{document}

وارتباط هذا المنطق بالمنطق الحدسي ظاهر في~$\LogGod[3]$: فكل حقيقة
حدسية تحصيل في~$\LogGod[3]$، وكثير من التحصيلات الكلاسيكية التي لا تصح حدسيًا لا
تكون تحصيلات في~$\LogGod[3]$ أيضًا. فمن أمثلتها هذه الصيغ:
\begin{align*}
  & p \lor \lnot p && (p \lif q) \lif (\lnot p \lor q) \\
  & \lnot\lnot p \lif p && \lnot(\lnot p \land \lnot q) \lif (p \lor q) \\
  & ((p \lif q) \lif p) \lif p && \lnot(p \lif q) \lif (p \land \lnot q)
\end{align*}
ومع ذلك توجد تحصيلات لـ~$\LogGod[3]$ لا تصح حدسيًا، ومنها
$\lnot\lnot p \lor \lnot p$ و~$(p \lif q) \lor (q \lif p)$.

\begin{prob}
  ضع جداول صدق تثبت أن الصيغ الآتية تحصيلات في~$\LogGod[3]$:
  \begin{align*}
    & \lnot\lnot p \lor \lnot p\\
    & (p \lif q) \lor (q \lif p) \\
    & \lnot(p \land q) \lif (\lnot p \lor \lnot q) \\
    & (p \lif q) \lor (q \lif r) \lor (r \lif s)
  \end{align*}
\end{prob}

\begin{prob}
  ضع جداول صدق تثبت أن الصيغ الآتية ليست تحصيلات في~$\LogGod[3]$:
  % تصحيح أسلوبي (0396-N1): استُعمل فعل الأمر بدل المصدر.
  \begin{align*}
    & (p \lif q) \lif (\lnot p \lor q) \\
    & \lnot(\lnot p \land \lnot q) \lif (p \lor q) \\
    & ((p \lif q) \lif p) \lif p \\
    & \lnot(p \lif q) \lif (p \land \lnot q)
  \end{align*}
\end{prob}

\begin{prob}
  أي العلاقات الآتية تصح في منطق غودل؟ ضع جدول صدق لكل واحدة.
  \begin{enumerate}
    \item $p, p \lif q \Entails q$
    \item $p \lor q, \lnot p \Entails q$
    \item $p \land q \Entails p$
    \item $p \Entails p \land p$
    \item $p \Entails p \lor q$
  \end{enumerate}
\end{prob}

\end{document}

