\begin{editorial}
  This is a short ``stub'' of a section on infinite-valued \L
  ukasiewicz logic.
\end{editorial}

\begin{defn}\ollabel{def:lukasiewicz} Infinite-valued \L ukasiewicz
logic~$\LogLuk[\infty]$ is defined using the matrix:
\begin{enumerate}
  \item The standard propositional language $\Lang L_0$ with
  $\lnot$, $\land$, $\lor$, $\lif$.
  \item The set of truth values $V_\infty$.
  \item $1$ is the only designated value, i.e., $V^+ = \{1\}$.
  \item Truth functions are given by the following functions:
  \begin{align*}
    \tf{\lnot}[\LogLuk](x) & = 1 - x\\
    \tf{\land}[\LogLuk](x,y) & = \min(x,y)\\
    \tf{\lor}[\LogLuk](x,y) & = \max(x,y)\\
    \tf{\lif}[\LogLuk](x,y) & = \min(1,1-(x-y)) = \begin{cases}
      1 & \text{if } x \le y\\
      1-(x-y) & \text{otherwise.}
    \end{cases}
    \end{align*}
\end{enumerate}
$m$-valued \L ukasiewicz logic is defined the same, except $V = V_m$.
\end{defn}

\begin{editorial}
  هذه ``بذرة'' قصيرة لقسم عن منطق~\L ukasiewicz اللانهائي القيم.
\end{editorial}

\begin{defn}\ollabel{def:lukasiewicz} يعرّف منطق~\L ukasiewicz
اللانهائي القيم~$\LogLuk[\infty]$ بالمصفوفة الآتية:
\begin{enumerate}
  \item الجزء الخالي من الثوابت~$\Lang L_0^{-}$ من لغة القضايا القياسية، بروابطه
  $\lnot$ و$\land$ و$\lor$ و$\lif$.
  % تصحيح مصدر مشترك (MVL-L0-I1): حُددت اللغة الخالية من lfalse التي تفسر المصفوفة جميع روابطها.
  \item مجموعة قيم الصدق~$V_\infty$.
  \item $1$ هي القيمة المميزة الوحيدة؛ أي~$V^+ = \{1\}$.
  \item تعطي الدوال الآتية دوال الصدق:
  \begin{align*}
    \tf{\lnot}[\LogLuk](x) & = 1 - x\\
    \tf{\land}[\LogLuk](x,y) & = \min(x,y)\\
    \tf{\lor}[\LogLuk](x,y) & = \max(x,y)\\
    \tf{\lif}[\LogLuk](x,y) & = \min(1,1-(x-y)) = \begin{cases}
      1 & \text{إذا كان } x \le y\\
      1-(x-y) & \text{في غير ذلك.}
    \end{cases}
    \end{align*}
\end{enumerate}
ويعرّف منطق~\L ukasiewicz ذو~$m$ من القيم بالطريقة نفسها، عدا أن
$V = V_m$.

\begin{editorial}
  ليس هذا إلا «بذرة» وجيزة لقسم في منطق~\L ukasiewicz اللانهائي القيم.
\end{editorial}

\begin{defn}\ollabel{def:lukasiewicz} مصفوفة منطق~\L ukasiewicz
اللانهائي القيم~$\LogLuk[\infty]$ هي:
\begin{enumerate}
  \item الجزء الخالي من الثوابت~$\Lang L_0^{-}$ من لغة القضايا القياسية، ذو الروابط
  $\lnot$ و$\land$ و$\lor$ و$\lif$.
  % تصحيح مصدر مشترك (MVL-L0-I1): حُددت اللغة الخالية من lfalse التي تفسر المصفوفة جميع روابطها.
  \item مجموعة قيم الصدق~$V_\infty$.
  \item القيمة المميزة وحدها هي~$1$؛ أي~$V^+ = \{1\}$.
  \item دوال الصدق هي الدوال الآتية:
  \begin{align*}
    \tf{\lnot}[\LogLuk](x) & = 1 - x\\
    \tf{\land}[\LogLuk](x,y) & = \min(x,y)\\
    \tf{\lor}[\LogLuk](x,y) & = \max(x,y)\\
    \tf{\lif}[\LogLuk](x,y) & = \min(1,1-(x-y)) = \begin{cases}
