The basic language of modal logic contains
\begin{enumerate}
  \tagitem{prvFalse}{The propositional constant for !!{falsity}~$\lfalse$.}{}
  \tagitem{prvTrue}{The propositional constant for !!{truth}~$\ltrue$.}{}
  \item A !!{denumerable}s set of !!{propositional variable}s: $\Obj
    p_0$, $\Obj p_1$, $\Obj p_2$, \dots
  \item The propositional connectives: \startycommalist
  \iftag{prvNot}{\ycomma $\lnot$ (negation)}{}%
  \iftag{prvAnd}{\ycomma $\land$ (conjunction)}{}%
  \iftag{prvOr}{\ycomma $\lor$ (disjunction)}{}%
  \iftag{prvIf}{\ycomma $\lif$ (!!{conditional})}{}%
  \iftag{prvIff}{\ycomma $\liff$ (!!{biconditional})}{}.
  \tagitem{prvBox}{The modal operator $\Box$.}{}
  \tagitem{prvDiamond}{The modal operator $\Diamond$.}{}
\end{enumerate}
\end{defn}

\begin{defn}
\emph{!!^{formula}s} of the basic modal language are inductively
  defined as follows:

تحتوي اللغة الأساسية للمنطق الموجهي على
\begin{enumerate}
  \tagitem{prvFalse}{ثابت القضايا للدلالة على !!{falsity}~$\lfalse$.}{}
  \tagitem{prvTrue}{ثابت القضايا للدلالة على !!{truth}~$\ltrue$.}{}
  \item مجموعة !!{denumerable}s من !!{propositional variable}s:
    $\Obj p_0$، و$\Obj p_1$، و$\Obj p_2$، و\dots
  \item روابط القضايا: \startycommalist
  \iftag{prvNot}{\ycomma $\lnot$ (النفي)}{}%
  \iftag{prvAnd}{\ycomma $\land$ (الاقتران)}{}%
  \iftag{prvOr}{\ycomma $\lor$ (الفصل)}{}%
  \iftag{prvIf}{\ycomma $\lif$ (!!{conditional})}{}%
  \iftag{prvIff}{\ycomma $\liff$ (!!{biconditional})}{}.
  \tagitem{prvBox}{المؤثر الموجهي~$\Box$.}{}
  \tagitem{prvDiamond}{المؤثر الموجهي~$\Diamond$.}{}
\end{enumerate}
\end{defn}

\begin{defn}
تُعرّف \emph{!!^{formula}s} اللغة الموجهية الأساسية استقرائيًا كما
يأتي:

أجزاء اللغة الأساسية للمنطق الموجهي هي الآتية:
\begin{enumerate}
  \tagitem{prvFalse}{ثابت القضايا للدلالة على !!{falsity}~$\lfalse$.}{}
  \tagitem{prvTrue}{ثابت القضايا للدلالة على !!{truth}~$\ltrue$.}{}
  \item مجموعة !!{denumerable}s من !!{propositional variable}s:
    $\Obj p_0$، و$\Obj p_1$، و$\Obj p_2$، و\dots
  \item روابط القضايا: \startycommalist
  \iftag{prvNot}{\ycomma $\lnot$ (النفي)}{}%
  \iftag{prvAnd}{\ycomma $\land$ (الاقتران)}{}%
  \iftag{prvOr}{\ycomma $\lor$ (الفصل)}{}%
  \iftag{prvIf}{\ycomma $\lif$ (!!{conditional})}{}%
  \iftag{prvIff}{\ycomma $\liff$ (!!{biconditional})}{}.
  \tagitem{prvBox}{المؤثر الموجهي~$\Box$.}{}
  \tagitem{prvDiamond}{المؤثر الموجهي~$\Diamond$.}{}
\end{enumerate}
\end{defn}

\begin{defn}
وأما \emph{!!^{formula}s} هذه اللغة، فيحدّها التعريف الاستقرائي
الآتي، مبتدئًا بالذرية ثم بوجوه التركيب:

\begin{tagblock}{defNot,defOr,defAnd,defIf,defIff,defTrue,defFalse,defBox,defDiamond}
\begin{defn}
Formulas constructed using the defined operators are to be understood
as follows:

\begin{tagenumerate}{defTrue,defFalse,defNot,defOr,defAnd,defIf,defIff,defBox,defDiamond}

\tagitem{defTrue}{$\ltrue$ abbreviates
  \iftag{prvFalse}{$\lnot\lfalse$}{$(!A \lor \lnot !A)$ for some
    fixed atomic !!{formula}~$!A$}.}{}

\tagitem{defFalse}{$\lfalse$ abbreviates
  \iftag{prvTrue}{$\lnot\ltrue$}{$(!A \land \lnot !A)$ for some
    fixed atomic !!{formula}~$!A$}.}{}

\tagitem{defNot}{$\lnot !A$ abbreviates $!A \lif \lfalse$.}{}

\tagitem{defOr}{$!A \lor !B$ abbreviates
  \iftag{prvAnd}{$\lnot(\lnot !A \land \lnot !B)$}{$\lnot !A \lif
    !B$}.}{}

\tagitem{defAnd}{$!A \land !B$ abbreviates
  \iftag{prvOr}{$\lnot(\lnot !A \lor \lnot !B)$}{$\lnot (!A \lif
    \lnot !B)$}.}{}

\tagitem{defIf}{$!A \lif !B$ abbreviates
  \iftag{prvOr}{$\lnot !A \lor !B)$}{$\lnot (!A \land \lnot !B)$}.}{}

\tagitem{defIff}{$!A \liff !B$ abbreviates $(!A \lif !B) \land (!B
  \lif !A)$.}{}

\tagitem{defBox}{$\Box !A$ abbreviates $\lnot\Diamond\lnot !A$. }{}

\tagitem{defDiamond}{$\Diamond !A$ abbreviates $\lnot\Box\lnot !A$.}{}
\end{tagenumerate}
\end{defn}
\end{tagblock}

If !!a{formula}~$!A$ does not contain $\Box$ or $\Diamond$, we say it
is \emph{modal-free}.

\begin{tagblock}{defNot,defOr,defAnd,defIf,defIff,defTrue,defFalse,defBox,defDiamond}
\begin{defn}
تُفهم الصيغ المبنية بالمؤثرات المعرّفة كما يأتي:

\begin{tagenumerate}{defTrue,defFalse,defNot,defOr,defAnd,defIf,defIff,defBox,defDiamond}

\tagitem{defTrue}{$\ltrue$ اختصار لـ
  \iftag{prvFalse}{$\lnot\lfalse$}{$(!A \lor \lnot !A)$ لبعض
    !!{formula} ذرية ثابتة~$!A$}.}{}

\tagitem{defFalse}{$\lfalse$ اختصار لـ
  \iftag{prvTrue}{$\lnot\ltrue$}{$(!A \land \lnot !A)$ لبعض
    !!{formula} ذرية ثابتة~$!A$}.}{}

\tagitem{defNot}{$\lnot !A$ اختصار لـ$!A \lif \lfalse$.}{}

\tagitem{defOr}{$!A \lor !B$ اختصار لـ
  \iftag{prvAnd}{$\lnot(\lnot !A \land \lnot !B)$}{$\lnot !A \lif
    !B$}.}{}

\tagitem{defAnd}{$!A \land !B$ اختصار لـ
  \iftag{prvOr}{$\lnot(\lnot !A \lor \lnot !B)$}{$\lnot (!A \lif
    \lnot !B)$}.}{}

\tagitem{defIf}{$!A \lif !B$ اختصار لـ
  \iftag{prvOr}{$(\lnot !A \lor !B)$}{$\lnot (!A \land \lnot !B)$}.}{}

\tagitem{defIff}{$!A \liff !B$ اختصار لـ$(!A \lif !B) \land (!B
  \lif !A)$.}{}

\tagitem{defBox}{$\Box !A$ اختصار لـ$\lnot\Diamond\lnot !A$. }{}

\tagitem{defDiamond}{$\Diamond !A$ اختصار لـ$\lnot\Box\lnot !A$.}{}
\end{tagenumerate}
\end{defn}
\end{tagblock}

إذا كانت !!a{formula}~$!A$ لا تحتوي~$\Box$ ولا~$\Diamond$، قلنا إنها
\emph{خالية من الجهات}.

\begin{tagblock}{defNot,defOr,defAnd,defIf,defIff,defTrue,defFalse,defBox,defDiamond}
\begin{defn}
وأما المؤثرات المعرّفة، فالصيغ المركبة بها اختصارات يُبيّن المراد
منها في البنود الآتية:

\begin{tagenumerate}{defTrue,defFalse,defNot,defOr,defAnd,defIf,defIff,defBox,defDiamond}

\tagitem{defTrue}{$\ltrue$ اختصار لـ
  \iftag{prvFalse}{$\lnot\lfalse$}{$(!A \lor \lnot !A)$ لبعض
    !!{formula} ذرية ثابتة~$!A$}.}{}

\tagitem{defFalse}{$\lfalse$ اختصار لـ
  \iftag{prvTrue}{$\lnot\ltrue$}{$(!A \land \lnot !A)$ لبعض
    !!{formula} ذرية ثابتة~$!A$}.}{}

\tagitem{defNot}{$\lnot !A$ اختصار لـ$!A \lif \lfalse$.}{}

\tagitem{defOr}{$!A \lor !B$ اختصار لـ
  \iftag{prvAnd}{$\lnot(\lnot !A \land \lnot !B)$}{$\lnot !A \lif
    !B$}.}{}

\tagitem{defAnd}{$!A \land !B$ اختصار لـ
  \iftag{prvOr}{$\lnot(\lnot !A \lor \lnot !B)$}{$\lnot (!A \lif
    \lnot !B)$}.}{}

\tagitem{defIf}{$!A \lif !B$ اختصار لـ
  \iftag{prvOr}{$(\lnot !A \lor !B)$}{$\lnot (!A \land \lnot !B)$}.}{}

\tagitem{defIff}{$!A \liff !B$ اختصار لـ$(!A \lif !B) \land (!B
  \lif !A)$.}{}

\tagitem{defBox}{$\Box !A$ اختصار لـ$\lnot\Diamond\lnot !A$. }{}

\tagitem{defDiamond}{$\Diamond !A$ اختصار لـ$\lnot\Box\lnot !A$.}{}
\end{tagenumerate}
\end{defn}
\end{tagblock}

ونسمي !!a{formula}~$!A$ \emph{خالية من الجهات} إذا لم يقع فيها
$\Box$ ولا~$\Diamond$.

